{"type":"message","message":{"id":"msg_4c5e730a-235a-4ff5-85f6-ac54459571e2","role":"user","created":1775255338,"content":[{"type":"toolResponse","id":"call_adae107ef0f93bbf","toolResult":{"status":"success","value":{"content":[{"type":"text","text":"\t\t\t\t\t<span>Historic exchange rates</span>\n\t\t\t\t\t<span>Current exchange rates</span>\n\t\t\t<li id=\"ca-view\" class=\"selected vector-tab-noicon mw-list-item\"><a href=\"/wiki/Indian_rupee\"><span>Read</span></a></li><li id=\"ca-edit\" class=\"vector-tab-noicon mw-list-item\"><a href=\"/w/index.php?title=Indian_rupee&amp;action=edit\" title=\"Edit this page [e]\" accesskey=\"e\"><span>Edit</span></a></li><li id=\"ca-history\" class=\"vector-tab-noicon mw-list-item\"><a href=\"/w/index.php?title=Indian_rupee&amp;action=history\" title=\"Past revisions of this page [h]\" accesskey=\"h\"><span>View history</span></a></li>\n\t\t\t<li id=\"ca-more-view\" class=\"selected vector-more-collapsible-item mw-list-item\"><a href=\"/wiki/Indian_rupee\"><span>Read</span></a></li><li id=\"ca-more-edit\" class=\"vector-more-collapsible-item mw-list-item\"><a href=\"/w/index.php?title=Indian_rupee&amp;action=edit\" title=\"Edit this page [e]\" accesskey=\"e\"><span>Edit</span></a></li><li id=\"ca-more-history\" class=\"vector-more-collapsible-item mw-list-item\"><a href=\"/w/index.php?title=Indian_rupee&amp;action=history\"><span>View history</span></a></li>\n<td style=\"vertical-align: middle; text-align: center;\"><span typeof=\"mw:File\"><a href=\"/wiki/File:Banknote_of_india.png\" class=\"mw-file-description\"><img src=\"//upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Banknote_of_india.png/250px-Banknote_of_india.png\" decoding=\"async\" width=\"126\" height=\"95\" class=\"mw-file-element\" srcset=\"//upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Banknote_of_india.png/330px-Banknote_of_india.png 2x\" data-file-width=\"2600\" data-file-height=\"1966\" /></a></span></td>\n<span class=\"skin-invert\" typeof=\"mw:File/Frameless\"><a href=\"/wiki/File:Indian_Paisa_symbol.svg\" class=\"mw-file-description\"><img src=\"//upload.wikimedia.org/wikipedia/commons/thumb/4/45/Indian_Paisa_symbol.svg/20px-Indian_Paisa_symbol.svg.png\" decoding=\"async\" width=\"10\" height=\"10\" class=\"mw-file-element\" data-file-width=\"480\" data-file-height=\"503\" /></a></span>25 (discontinued, not legal tender)</td></tr><tr><th colspan=\"2\" class=\"infobox-header\" style=\"background-color: lightskyblue;color:inherit;\">Demographics</th></tr><tr><th scope=\"row\" class=\"infobox-label\">Date of introduction</th><td class=\"infobox-data\">1835<span class=\"noprint\">&#59;&#32;191&#160;years ago</span><span style=\"display:none\">&#160;(<span class=\"bday dtstart published updated\">1835</span>)</span></td></tr><tr><th scope=\"row\" class=\"infobox-label\"><span class=\"nowrap\">Official user(s)</span></th><td class=\"infobox-data\"><style data-mw-deduplicate=\"TemplateStyles:r1126788409\">.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0}</style><div class=\"plainlist\"><ul><li><span class=\"flagicon nowrap\"><span class=\"mw-image-border\" typeof=\"mw:File\"><span><img alt=\"\" src=\"//upload.wikimedia.org/wikipedia/en/thumb/4/41/Flag_of_India.svg/40px-Flag_of_India.svg.png\" decoding=\"async\" width=\"23\" height=\"15\" class=\"mw-file-element\" srcset=\"//upload.wikimedia.org/wikipedia/en/thumb/4/41/Flag_of_India.svg/60px-Flag_of_India.svg.png 2x\" data-file-width=\"900\" data-file-height=\"600\" /></span></span> </span><a href=\"/wiki/India\" title=\"India\">India</a></li><li><span class=\"flagicon nowrap\"><span class=\"mw-image-border\" typeof=\"mw:File\"><span><img alt=\"\" src=\"//upload.wikimedia.org/wikipedia/commons/thumb/9/91/Flag_of_Bhutan.svg/40px-Flag_of_Bhutan.svg.png\" decoding=\"async\" width=\"23\" height=\"15\" class=\"mw-file-